348  void
   349  _uri_encoder (GString      *out,
   350                const guchar *start,
   351                gsize         length,
   352                const gchar  *reserved_chars_allowed,
   353                gboolean      allow_utf8)
   354  {
   355    static const gchar hex[16] = "0123456789ABCDEF";
   356    const guchar *p = start;
   357    const guchar *end = p + length;
   358
   359    while (p < end)
   360      {
   361        if (allow_utf8 && *p >= 0x80 &&
   362            g_utf8_get_char_validated ((gchar *)p, end - p) > 0)
   363          {
   364            gint len = g_utf8_skip [*p];
   365            g_string_append_len (out, (gchar *)p, len);
   366            p += len;
   367          }
   368        else if (is_valid (*p, reserved_chars_allowed))
   369          {
   370            g_string_append_c (out, *p);
   371            p++;
   372          }
   373        else
   374          {
   375            g_string_append_c (out, '%');
   376            g_string_append_c (out, hex[*p >> 4]);
   377            g_string_append_c (out, hex[*p & 0xf]);
   378            p++;
   379          }
   380      }
   381  }
