   383  static gboolean
   384  parse_host (const gchar  *start,
   385              gsize         length,
   386              GUriFlags     flags,
   387              gchar       **out,
   388              GError      **error)
   389  {
   390    gchar *decoded, *host, *pct;
   391    gchar *addr = NULL;
   392
   393    if (*start == '[')
   394      {
   395        if (start[length - 1] != ']')
   396          {
   397          bad_ipv6_literal:
   398            g_free (addr);
   399            g_set_error (error, G_URI_ERROR, G_URI_ERROR_BAD_HOST,
   400                         _("Invalid IPv6 address '%.*s' in URI"),
   401                         (gint)length, start);
   402            return FALSE;
   403          }
   404
   405        addr = g_strndup (start + 1, length - 2);
   406
   407        /* If there's an IPv6 scope id, ignore it for the moment. */
   408        pct = strchr (addr, '%');
   409        if (pct)
   410          *pct = '\0';
   411
   412        /* addr must be an IPv6 address */
   413        if (!g_hostname_is_ip_address (addr) || !strchr (addr, ':'))
   414          goto bad_ipv6_literal;
   415
   416        if (pct)
   417          {
   418            *pct = '%';
   419            if (strchr (pct + 1, '%'))
   420              goto bad_ipv6_literal;
   421            /* If the '%' is encoded as '%25' (which it should be), decode it */
   422            if (pct[1] == '2' && pct[2] == '5' && pct[3])
   423              memmove (pct + 1, pct + 3, strlen (pct + 3) + 1);
   424          }
   425
   426        host = addr;
   427        goto ok;
   428      }
   429
   430    if (g_ascii_isdigit (*start))
   431      {
   432        addr = g_strndup (start, length);
   433        if (g_hostname_is_ip_address (addr))
   434          {
   435            host = addr;
   436            goto ok;
   437          }
   438        g_free (addr);
   439      }
   440
   441    if (flags & G_URI_FLAGS_NON_DNS)
   442      {
   443        if (!uri_normalize (&decoded, start, length, flags,
   444                            G_URI_ERROR_BAD_HOST, error))
   445          return FALSE;
   446        host = decoded;
   447        goto ok;
   448      }
   449
   450    flags &= ~G_URI_FLAGS_ENCODED;
   451    if (!uri_decode (&decoded, start, length, flags,
   452                     G_URI_ERROR_BAD_HOST, error))
   453      return FALSE;
   454
   455    /* You're not allowed to %-encode an IP address, so if it wasn't
   456     * one before, it better not be one now.
   457     */
   458    if (g_hostname_is_ip_address (decoded))
   459      {
   460        g_free (decoded);
   461        g_set_error (error, G_URI_ERROR, G_URI_ERROR_BAD_HOST,
   462                     _("Illegal encoded IP address '%.*s' in URI"),
   463                     (gint)length, start);
   464        return FALSE;
   465      }
   466
   467    if (g_hostname_is_non_ascii (decoded))
   468      {
   469        host = g_hostname_to_ascii (decoded);
   470        g_free (decoded);
   471      }
   472    else
   473      host = decoded;
   474
   475   ok:
   476    if (out)
   477      *out = host;
   478    else
   479      g_free (host);
   480    return TRUE;
   481  }
