   483  static gboolean
   484  parse_port (const gchar  *start,
   485              gsize         length,
   486              gint         *out,
   487              GError      **error)
   488  {
   489    gchar *end;
   490    gulong parsed_port;
   491
   492    /* strtoul() allows leading + or -, so we have to check this first. */
   493    if (!g_ascii_isdigit (*start))
   494      {
   495        g_set_error (error, G_URI_ERROR, G_URI_ERROR_BAD_PORT,
   496                     _("Could not parse port '%.*s' in URI"),
   497                     (gint)length, start);
   498        return FALSE;
   499      }
   500
   501    /* We know that *(start + length) is either '\0' or a non-numeric
   502     * character, so strtoul() won't scan beyond it.
   503     */
   504    parsed_port = strtoul (start, &end, 10);
   505    if (end != start + length)
   506      {
   507        g_set_error (error, G_URI_ERROR, G_URI_ERROR_BAD_PORT,
   508                     _("Could not parse port '%.*s' in URI"),
   509                     (gint)length, start);
   510        return FALSE;
   511      }
   512    else if (parsed_port > 65535)
   513      {
   514        g_set_error (error, G_URI_ERROR, G_URI_ERROR_BAD_PORT,
   515                     _("Port '%.*s' in URI is out of range"),
   516                     (gint)length, start);
   517        return FALSE;
   518      }
   519
   520    if (out)
   521      *out = parsed_port;
   522    return TRUE;
   523  }
